alter policy grd_run_owner on public.grd_run_saves using ((select auth.uid())=user_id and (select auth.jwt())->'app_metadata'->>'grd_named_account'='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false') with check ((select auth.uid())=user_id and (select auth.jwt())->'app_metadata'->>'grd_named_account'='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false');
alter policy grd_season_insert on public.grd_season_scores with check ((select auth.uid())=user_id and (select auth.jwt())->'app_metadata'->>'grd_named_account'='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false' and exists(select 1 from public.grd_nicknames n where n.user_id=(select auth.uid()) and n.nickname=grd_season_scores.nickname));
alter policy grd_season_update on public.grd_season_scores using ((select auth.uid())=user_id and (select auth.jwt())->'app_metadata'->>'grd_named_account'='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false') with check ((select auth.uid())=user_id and (select auth.jwt())->'app_metadata'->>'grd_named_account'='true' and coalesce((select auth.jwt())->>'is_anonymous','false')='false' and exists(select 1 from public.grd_nicknames n where n.user_id=(select auth.uid()) and n.nickname=grd_season_scores.nickname));